    return f"{middle} and {filtered_words[-1]}"

def repeat_sequence_len(a0):
    def F(N):
        return sum(int(digit) ** 2 for digit in str(N))

    seen = set()
    current = a0

    while current not in seen:
        seen.add(current)
        current = F(current)

    # The length of the sequence is the number of elements in the set minus one
    return len(seen) - 1

