def create_anagram(s, t):
    # Count the frequency of each character in s
    s_count = {}
    for char in s:
        if char in s_count:
            s_count[char] += 1
        else:
            s_count[char] = 1

    # Count the frequency of each character in t
    t_count = {}
    for char in t:
        if char in t_count:
            t_count[char] += 1
        else:
            t_count[char] = 1

    # Calculate the minimum number of replacements needed
    replacements = 0
    for char in s:
        if char in t_count:
            replacements += abs(s_count[char] - t_count[char])
        else:
            replacements += s_count[char]

    return replacements

def count_squares(lines):
    count = 0
    n = len(lines)
    m = len(lines[0])

    # Helper function to check if a square is valid
    def is_valid_square(x, y, size):
        if x + size > n or y + size > m:
            return False
        for i in range(size):
            for j in range(size):
                if lines[x + i][y + j] != '+':
                    return False
        return True

    # Iterate over all potential center points
    for i in range(n):
        for j in range(m):
            # Check all possible square sizes starting from 2
            for size in range(2, min(n - i, m - j) + 1):
                if is_valid_square(i, j, size):
                    count += 1

    return count

