def no_order(equation):
    if not equation:
        return None

    # Tokenize the equation
    tokens = []
    i = 0
    while i < len(equation):
        if equation[i].isdigit():
            j = i
            while j < len(equation) and equation[j].isdigit():
                j += 1
            tokens.append(int(equation[i:j]))
            i = j
        else:
            tokens.append(equation[i])
            i += 1

    # Evaluate the expression from left to right
    result = tokens[0]
    i = 1
    while i < len(tokens):
        token = tokens[i]
        if token == '+':
            result += tokens[i + 1]
        elif token == '-':
            result -= tokens[i + 1]
        elif token == '*':
            result *= tokens[i + 1]
        elif token == '/':
            if tokens[i + 1] == 0:
                return None
            result //= tokens[i + 1]
        elif token == '^':
            result **= tokens[i + 1]
        elif token == '%':
            if tokens[i + 1] == 0:
                return None
            result %= tokens[i + 1]
        i += 2

    return result

