def convergence(n):
    def next_number(x):
        if len(str(x)) == 1:
            return x + x
        else:
            product = 1
            for digit in str(x):
                if digit != '0':
                    product *= int(digit)
            return x + product

    base_series = {1, 2, 4, 8, 16, 22, 26, 38, 62, 74, 102, 104, 108, 116, 122}
    current = n
    count = 0

    while current not in base_series:
        current = next_number(current)
        count += 1

    return count

