def no_order(equation):
    if not equation:
        return None

    # Remove spaces from the equation
    equation = equation.replace(' ', '')

    # Check for division by zero
    if ' / 0' in equation:
        return None

    # Initialize the result with the first number
    result = int(equation[0])

    # Iterate through the equation
    i = 1
    while i < len(equation):
        char = equation[i]
        if char == '+':
            result += int(equation[i + 1])
            i += 2
        elif char == '-':
            result -= int(equation[i + 1])
            i += 2
        elif char == '*':
            result *= int(equation[i + 1])
            i += 2
        elif char == '%':
            result %= int(equation[i + 1])
            i += 2
        elif char == '^':
            result **= int(equation[i + 1])
            i += 2
        else:
            # This should not happen as we only have allowed operations
            return None

    return result

def hamster_me(code, message):
    # Create a mapping of letters to their corresponding numbers
    code_map = {}
    current_number = 1
    for char in code:
        if char not in code_map:
            code_map[char] = current_number
            current_number += 1

    # Iterate over each character in the message
    result = []
    for char in message:
        # Get the encrypted number for the character
        encrypted_number = code_map.get(char, 1)
        result.append(str(encrypted_number))

    # Join the result list into a string
    return ''.join(result)

def est_subsets(arr):
    def is_valid_subset(subset):
        # Check if any element appears more than once in the subset
        return len(subset) == len(set(subset))

    def generate_subsets(index, current_subset):
        # Base case: if we've reached the end of the array
        if index == len(arr):
            # Check if the current subset is valid
            if is_valid_subset(current_subset):
                valid_subsets.add(current_subset)
            return

        # Include the current element in the subset
        generate_subsets(index + 1, current_subset + [arr[index]])

        # Exclude the current element from the subset
        generate_subsets(index + 1, current_subset)

    valid_subsets = set()
    generate_subsets(0, [])
    return len(valid_subsets)

