def remove_parentheses(s):
    result = []
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                result.append(char)
        else:
            result.append(char)

    return ''.join(result)

