def prime_string(s):
    if len(s) <= 1:
        return False
    for i in range(1, len(s)):
        if len(s) % i == 0:
            substring = s[:i]
            if all(s[j:j+i] == substring for j in range(i, len(s), i)):
                return False
    return True

